// InboxAuditing declares automatic auditing for normal lifecycle writes. Register it once through audit.Register.
// Existing observer registration owns dependency construction, duplicate detection and transaction lifetime.
func InboxAuditing(policy InboxAuditPolicy) record.Declaration {
	return record.Declare(func(registrar *foundation.Registrar, pool foundation.Key[*database.DB], resolve record.ResolveWriter) error {
		name, err := record.ObserverName[Inbox]()
		if err != nil {
			return err
		}
		return RegisterInboxObserver(registrar, pool, NewInboxObserver(name), func(resolver foundation.Resolver) (func() InboxHooks, error) {
			writer, err := resolve(resolver)
			if err != nil {
				return nil, err
			}
			if writer == nil {
				return nil, foundryfault.New(foundryfault.Invalid, "audit writer is not initialized")
			}
			return func() InboxHooks {
				write := func(ctx context.Context, tx *database.Tx, changes InboxChanges) error {
					captured, err := changes.Audit(policy)
					if err != nil {
						return err
					}
					return writer.RecordModel(ctx, tx, captured.Entry())
				}
				return InboxHooks{Created: write, Updated: write, Deleted: write, Restored: write}
			}, nil
		})
	})
}
